files = sorted(glob.glob('src/data/*.js'))
txt = {f: open(f, encoding='utf8').read() for f in files}
bad = 0
for old, new in R:
    hits = [f for f in files if old in txt[f]]
    if len(hits) != 1 or txt[hits[0]].count(old) != 1:
        print('NO ENCONTRADO/AMBIGUO:', old[:90]); bad += 1; continue
    txt[hits[0]] = txt[hits[0]].replace(old, new)
for f in files: open(f, 'w', encoding='utf8').write(txt[f])
print('aplicados', len(R) - bad, 'de', len(R))
